click.script:
const url = partner.data && partner.data.website;
if (url) {
  window.open(url.startsWith('http') ? url : 'https://' + url, '_blank', 'noopener');
} else {
  toast({ title: 'No website on file', text: 'This partner has not added a website yet', icon: 'info' });
}

if (!myContext.data || !myContext.data.customer) {
  goToSignIn();
  return;
}
const partnerName = route.params.partner_id;
const previous = myShortlist.data || [];
const wasShortlisted = previous.includes(partnerName);
myShortlist.data = wasShortlisted ? previous.filter((n) => n !== partnerName) : [...previous, partnerName];
const fn = wasShortlisted ? 'connect.api.customer.remove_from_shortlist' : 'connect.api.customer.add_to_shortlist';
call(fn, { partner: partnerName }).then(() => { myShortlist.reload(); }).catch((err) => {
  myShortlist.data = previous;
  toast({ title: 'Could not update shortlist', text: (err && err.message) || 'Please try again', icon: 'x' });
});

reviewSubmitting.value = true;
call('connect.api.partner.submit_partner_review', { partner: route.params.partner_id, rating: reviewRating.value, headline: reviewHeadline.value, quote: reviewQuote.value }).then(() => {
  toast.success('Thanks for your review. It is on the profile now.');
  reviewDialogOpen.value = false;
  reviewSubmitting.value = false;
  partnerReviews.reload();
  partner.reload();
}).catch((error) => {
  reviewSubmitting.value = false;
  toast.error((error && error.messages && error.messages[0]) || 'Could not submit your review. Try again.');
});
